export default () => (
  <main className="flex min-h-screen items-center justify-center bg-[#f3f0e8]">
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Newsreader:ital,wght@1,300&display=swap');
      @keyframes calm-in { from { opacity: 0; } to { opacity: 1; } }
    `}</style>
    <p
      style={{
        fontFamily: "'Newsreader', serif",
        fontStyle: "italic",
        fontWeight: 300,
        fontSize: "22px",
        letterSpacing: "0.02em",
        color: "#8b857a",
        animation: "calm-in 2.4s ease-out both",
      }}
    >
      hello
    </p>
  </main>
);

